import java.util.*

fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextLong()
    val fib = mutableListOf(1L, 2L)
    while (fib.last() < n) {
        fib.add(fib[fib.size - 1] + fib[fib.size - 2])
    }
    var count = 0
    var remaining = n
    var i = fib.size - 1
    while (remaining > 0 && i >= 0) {
        if (fib[i] <= remaining) {
            remaining -= fib[i]
            count++
        }
        i--
    }
    println(count)
}
