import java.math.BigInteger

fun main() {
    val n = readLine()!!.toBigInteger()
    val fib = mutableListOf<BigInteger>(BigInteger.ZERO, BigInteger.One, BigInteger.valueOf(2))
    while (fib.last() <= n) {
        val next = fib[fib.size - 1] + fib[fib.size - 2]
        fib.add(next)
    }
    var count = 0
    var remaining = n
    for (i in fib.size - 1 downTo 1) {
        if (fib[i] <= remaining) {
            remaining -= fib[i]
            count++
        }
    }
    println(count)
}
